<script setup>
import { computed, ref } from 'vue'
import { mineTime } from '../utils.mjs'
const props = defineProps({ record: [Object, Array], depth: { type: Number, default: 0 } })
const opened = ref({})
const labels = { kind: '记录类型', event_id: '事件编号', event_type: '事件类型', event_revision: '事件修订', point_id: '测点', source_id: '来源编号', session_id: '会话编号', sample_id: '样本编号', task_id: '任务编号', run_id: '预测运行', id: '记录编号', observation_id: '观测编号', source_file_id: '源文件标识', row_number: '原始行号', start_at: '开始时间', end_at: '结束时间', event_time: '观测时间', available_at: '数据可用时间', as_of: '数据截止', data_as_of: '数据时点', cutoff: '预测输入截止', revision_as_of: '修订截止', target_start_at: '目标开始', target_end_at: '目标结束', value: '有效值', raw_value: '原始值', unit: '单位', actual_value: '实测统计值', predicted_value: '预测值', actual_positive: '实测是否正样本', predicted_positive: '预测是否正样本', alert_level: '预警等级', state: '状态', status: '状态', model_id: '模型编号', model_version: '模型版本', rule_version: '规则版本', prediction_stage: '预测输出', evidence_refs: '依据引用', source_refs: '来源引用', input_refs: '输入引用', observation_refs: '实测引用', observation_snapshots: '冻结观测', observations: '冻结观测', forecast_run: '冻结预测运行', forecast_run_snapshot: '冻结预测运行', event_snapshot: '冻结事件', actions: '人工操作', advice_versions: '建议版本', source_case_snapshot: '处置快照', reference_ids: '资料引用', quality_flags: '质量标记', missing_fields: '缺项', valid: '有效性', evidence_complete: '依据是否完整', normal_task: '是否正常任务', advice_items: '建议条数', referenced_advice_items: '有出处建议条数', classification: '样本类别', physical_stage: '物理输出阶段' }
Object.assign(labels, { issued_at: '预测发出时间', notification_start_at: '预警发出时间', notification_end_at: '预警通知结束', interval_start_at: '预测目标开始', interval_end_at: '预测目标结束', advice_id: '建议编号', version: '版本', items: '建议条目', text: '引用原文', locator: '原文定位', reference_id: '引用编号', entry_id: '资料编号', source: '资料来源', page: '原文页码', paragraph: '原文段号', table: '原文表号', row: '表格行号', absolute_error: '绝对误差', percentage_error: '百分比误差' })
Object.assign(labels, { outputs: '预测输出', interval_values: '预测区间', target_statistic: '实测汇总方式', threshold: '判定阈值', interval_index: '目标区间序号', quantity_semantics: '输出含义' })
const names = { mean: '均值', max: '最大值', physical_forecast: '物理浓度预测', baseline_persistence: '持久性基线', residual_corrected: '残差修正预测', not_ready: '数据未齐', invalid_value: '无效值', planned_calibration: '计划标校', confirmed_calibration: '已确认标校', duplicate_timestamp: '重复时间', unit_inferred: '单位推定', timezone_inferred: '时区按配置', forward_filled: '过去值填补', lineage_processed: '加工历史', delayed: '延迟', completed: '已完成', failed: '失败', partial: '部分完成', cancelled: '已取消', running: '进行中', awaiting_input: '待补充', queued: '排队中', observed_exceedance: '会话实测阈值事件', forecast_exceedance: '预测预警', red: '红色', orange: '橙色', yellow: '黄色', blue: '蓝色', suspected_calibration: '疑似标校', invalid: '无效', missing: '缺测' }
const entries = computed(() => Array.isArray(props.record) ? props.record.map((value, i) => [String(i + 1), value]) : Object.entries(props.record || {}).filter(([key]) => labels[key]))
const show = value => typeof value === 'boolean' ? value ? '是' : '否' : typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(value) ? mineTime(value) : names[value] || String(value ?? '—')
</script>
<template>
  <div v-if="Array.isArray(record)" class="frozen-records"><article v-for="(item,index) in record.slice(0,50)" :key="index"><strong>记录{{ index + 1 }}</strong><FrozenRecord v-if="item && typeof item === 'object'" :record="item" :depth="depth + 1" /><p v-else>{{ show(item) }}</p></article><p v-if="record.length > 50" class="muted">本页展开前50条，完整记录见报告下载。</p></div>
  <dl v-else class="frozen-record"><template v-for="([key,value]) in entries" :key="key">
    <template v-if="value === null || typeof value !== 'object'"><dt>{{ labels[key] || `记录${key}` }}</dt><dd>{{ show(value) }}</dd></template>
    <template v-else-if="Array.isArray(value) && value.every(item => item === null || typeof item !== 'object')"><dt>{{ labels[key] || `记录${key}` }}</dt><dd>{{ value.map(show).join('、') || '无' }}</dd></template>
    <div v-else class="frozen-nested"><details @toggle="opened[key] = $event.target.open"><summary>{{ labels[key] || `记录${key}` }}{{ Array.isArray(value) ? ` · ${value.length}条` : '' }}</summary><FrozenRecord v-if="opened[key] && depth < 4" :record="value" :depth="depth + 1" /><p v-else-if="opened[key]" class="muted">完整记录见冻结报告下载。</p></details></div>
  </template></dl>
</template>
<style scoped>
.frozen-record{display:grid;grid-template-columns:minmax(95px,125px) minmax(0,1fr);gap:7px 12px;font-size:12px;line-height:1.65;margin:10px 0}.frozen-record dt{color:#8eaec3}.frozen-record dd{margin:0;overflow-wrap:anywhere;color:#c6dce9}.frozen-nested{grid-column:1/-1;min-width:0;border-top:1px solid #27465c;padding-top:7px}.frozen-nested summary{color:#8fd3df;cursor:pointer}.frozen-nested>details>.frozen-record{padding-left:8px}
.frozen-records>article{margin-top:10px;padding-left:9px;border-left:1px solid #365569}.frozen-records>article>strong{font-size:12px;font-weight:400;color:#90b4ca}
</style>
